"""A beta-only retailer profile using a dated public catalogue snapshot.

No API adapter, click tracking, advertiser account or ranking claims are added.
"""
import base64
from collections import Counter
from html import escape as e
import json
from pathlib import Path

STYLE = '''<style>
.sp-store{padding:24px 0 48px;color:var(--sp-ink)}.sp-store [hidden]{display:none!important}.sp-store a{color:var(--sp-green);text-underline-offset:4px}.sp-store p{line-height:1.65}.sp-store .muted{color:var(--sp-muted);font-size:14px}.sp-store .store-back{display:inline-flex;align-items:center;min-height:44px}.store-hero{display:grid;grid-template-columns:144px 1fr auto;gap:24px;align-items:center;margin:16px 0 24px}.store-logo{width:144px;height:120px;border:1px solid var(--sp-line);border-radius:16px;display:flex;align-items:center;justify-content:center;background:white;padding:16px;box-sizing:border-box}.store-logo img{width:100%;height:100%;object-fit:contain}.sp-store h1{font-size:40px;line-height:1.2;margin:4px 0 12px}.store-hero p{max-width:650px;margin:0}.store-eyebrow{font-size:13px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--sp-muted)}.sp-store .store-link{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 16px;border:1px solid var(--sp-line);border-radius:8px;text-decoration:none;font-weight:600;box-sizing:border-box}.store-facts{display:flex;gap:32px;background:var(--sp-mint);border-radius:12px;padding:18px 24px;margin:0 0 16px}.store-facts div{display:flex;gap:8px;align-items:baseline}.store-facts dt{order:2;font-size:14px}.store-facts dd{margin:0;font-size:24px;font-weight:700}.store-nav{display:flex;gap:24px;flex-wrap:wrap;border-bottom:1px solid var(--sp-line);margin:24px 0}.store-nav a{display:flex;align-items:center;min-height:48px;font-weight:600;text-decoration:none}.sp-store h2{font-size:26px;line-height:1.25;margin:0 0 12px}.store-section{scroll-margin-top:24px;margin:32px 0 0}.store-toolbar{display:grid;grid-template-columns:1fr 220px;gap:16px;max-width:780px;margin:20px 0 16px}.sp-store label{display:grid;gap:8px;font-size:14px;font-weight:600}.sp-store input,.sp-store select,.sp-store button{font:inherit;min-height:44px;border:1px solid var(--sp-line);border-radius:8px;padding:10px 12px;background:white;color:var(--sp-ink);box-sizing:border-box;max-width:100%}.sp-store button{cursor:pointer}.sp-store :focus-visible{outline:3px solid #177fc5;outline-offset:3px}.store-filters{display:flex;gap:8px;flex-wrap:wrap}.store-filters button{font-size:14px;border-radius:24px}.store-filters button[aria-pressed=true]{background:var(--sp-ink);color:white;border-color:var(--sp-ink)}.store-filters span{opacity:.75;margin-left:8px}.store-results-status{font-size:14px;color:var(--sp-muted);margin:16px 0}.store-products{padding:0;margin:0;list-style:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.store-card{border:1px solid var(--sp-line);border-radius:12px;padding:20px;display:flex;flex-direction:column;min-width:0}.store-card img{width:100%;height:180px;object-fit:contain;margin-bottom:16px}.store-card h3{font-size:17px;line-height:1.4;margin:4px 0 16px;min-height:48px}.store-card h3 a{color:var(--sp-ink);text-decoration:none;display:block}.store-card h3 a:hover{text-decoration:underline}.store-card .store-price{margin-top:auto;margin-bottom:16px}.store-card .store-price p{margin:0}.store-card strong{display:block;font-size:24px;margin:4px 0}.store-card .store-link{background:var(--sp-green);color:white;border-color:var(--sp-green)}.store-card .category{font-size:12px;color:var(--sp-muted);margin:0}.store-more{margin:20px auto 0;display:block;min-width:220px}.store-empty{padding:32px;background:#f5f7fa;border-radius:12px}.store-lower{display:grid;grid-template-columns:1.2fr 1fr;gap:24px;margin-top:40px}.store-panel{border:1px solid var(--sp-line);border-radius:12px;padding:24px}.store-panel h3{font-size:18px;margin:20px 0 8px}.store-panel p{margin:8px 0}.store-panel .store-link{margin-top:8px}.store-bars{list-style:none;padding:0;margin:20px 0}.store-bars li{margin:16px 0}.store-bar-label{display:flex;justify-content:space-between;gap:16px;font-size:14px;margin-bottom:8px}.store-track{height:6px;background:#edf1f4;border-radius:4px;overflow:hidden}.store-track span{display:block;height:100%;background:#338a73;border-radius:4px}.store-popularity{background:#f6f9f8;border-radius:10px;padding:20px;margin-top:24px}.store-popularity h3{margin:0 0 8px}.store-about dl{margin:20px 0}.store-about dl div{padding:12px 0;border-bottom:1px solid var(--sp-line)}.store-about dt{font-size:13px;color:var(--sp-muted);margin-bottom:6px}.store-about dd{margin:0;font-size:15px}.store-sources{border-top:1px solid var(--sp-line);padding-top:20px;margin-top:32px}.store-sources summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:600}.store-sources summary:before{content:'＋';margin-right:12px}.store-sources[open] summary:before{content:'−'}.store-sources li{line-height:1.7;margin:8px 0}.store-sources a{display:inline-flex;min-height:44px;align-items:center}
@media(max-width:999px){.store-hero{grid-template-columns:112px 1fr}.store-logo{width:112px;height:104px}.store-hero>.store-link{grid-column:2;justify-self:start}.store-lower{grid-template-columns:1fr 1fr}.store-products{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:599px){.sp-store{padding-top:16px}.store-hero{grid-template-columns:80px 1fr;gap:16px;margin-top:8px}.store-logo{width:80px;height:80px;padding:8px}.sp-store h1{font-size:30px}.store-hero .store-intro{grid-column:1/-1}.store-hero>.store-link{grid-column:1/-1;justify-self:stretch}.store-facts{gap:12px;padding:16px;justify-content:space-between}.store-facts div{display:block}.store-facts dt{font-size:12px}.store-facts dd{font-size:22px}.store-nav{gap:8px 20px;margin-top:16px}.store-toolbar{grid-template-columns:1fr}.store-products{gap:12px}.store-card{padding:12px}.store-card img{height:132px;margin-bottom:12px}.store-card h3{font-size:14px;margin-bottom:12px;min-height:60px}.store-card .category{display:none}.store-card strong{font-size:21px}.store-card .muted{font-size:12px}.store-card .store-link{padding:8px;font-size:13px}.store-lower{grid-template-columns:1fr;gap:16px;margin-top:32px}.store-panel{padding:20px}.sp-store h2{font-size:23px}}
</style>'''

SCRIPT = '''<script>(()=>{
const root=document.querySelector('.sp-store'), list=root.querySelector('.store-products'), cards=Array.from(list.children), search=root.querySelector('#store-query'), sort=root.querySelector('#store-sort'), more=root.querySelector('#store-more'), empty=root.querySelector('#store-empty'), buttons=Array.from(root.querySelectorAll('[data-store-filter]'));
let category='',limit=6;
function render(){const q=search.value.trim().toLocaleLowerCase('nb-NO');let matches=cards.filter(c=>(!category||c.dataset.category===category)&&c.dataset.name.toLocaleLowerCase('nb-NO').includes(q));matches.sort((a,b)=>sort.value==='price'?Number(a.dataset.price)-Number(b.dataset.price):a.dataset.name.localeCompare(b.dataset.name,'nb'));cards.forEach(c=>c.hidden=true);matches.forEach((c,i)=>{list.append(c);c.hidden=i>=limit});more.hidden=matches.length<=limit;empty.hidden=matches.length>0;root.querySelector('#store-status').textContent='Viser '+Math.min(limit,matches.length)+' av '+matches.length+' produkter'+(matches.length!==cards.length?' · '+cards.length+' i hele utvalget':'');buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.storeFilter===category)));}
root.querySelector('#store-controls').hidden=false;buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.storeFilter;limit=6;render()}));search.addEventListener('input',()=>{limit=6;render()});sort.addEventListener('change',()=>{limit=6;render()});more.addEventListener('click',()=>{const first=limit;limit=cards.length;render();list.querySelectorAll('li:not([hidden])')[first]?.querySelector('h3 a').focus()});root.querySelector('#store-reset').addEventListener('click',()=>{search.value='';category='';limit=6;render();search.focus()});render();})();</script>'''


def build_store_preview(out):
    from home_release import page
    source=Path(__file__).parent/'design_assets/babybrezza-snapshot.json'
    data=json.loads(source.read_text(encoding='utf-8'))
    products=data['products'];count=len(products);groups=Counter(p['category'] for p in products)
    assets=out/'assets'/'babybrezza';assets.mkdir(parents=True,exist_ok=True)
    (assets/'logo.webp').write_bytes(base64.b64decode(data['logo_webp']))
    cards=[]
    for i,p in enumerate(products):
        (assets/f'{i}.webp').write_bytes(base64.b64decode(p['image_webp']))
        cards.append(f'''<li class="store-card" data-name="{e(p['name'])}" data-category="{e(p['category'])}" data-price="{p['price_minor']}"><img src="/assets/babybrezza/{i}.webp" alt="" width="360" height="360" loading="lazy"><p class="category">{e(p['category'])}</p><h3><a href="{e(p['url'])}">{e(p['name'].removeprefix('Baby Brezza '))}</a></h3><div class="store-price"><p class="muted">Varepris hos Baby Brezza</p><strong>{e(p['price'])}</strong><p class="muted">Frakt ukjent · 18.10.2026</p></div><a class="store-link" href="{e(p['url'])}">Se produkt og pris →</a></li>''')
    chips='<button type="button" data-store-filter="" aria-pressed="true">Alle<span>'+str(count)+'</span></button>'+''.join(f'<button type="button" data-store-filter="{e(k)}" aria-pressed="false">{e(k)}<span>{n}</span></button>' for k,n in groups.items())
    bars=''.join(f'<li><div class="store-bar-label"><span>{e(k)}</span><strong>{n}</strong></div><div class="store-track" aria-hidden="true"><span style="width:{n/count*100:.2f}%"></span></div></li>' for k,n in groups.items())
    body=STYLE+f'''<article class="sp-store"><a class="store-back" href="/butikker/">← Alle butikker</a>
<header class="store-hero"><div class="store-logo"><img src="/assets/babybrezza/logo.webp" alt="Baby Brezza" width="144" height="120"></div><div><p class="store-eyebrow">Butikk på SjekkPris</p><h1>Baby Brezza</h1><p class="muted">babybrezza.no</p></div><a class="store-link" href="https://babybrezza.no/">Besøk nettbutikken ↗</a><p class="store-intro" style="grid-column:1/-1">Finn produkter fra Baby Brezza innen flaskemating og matlaging. Her samler vi butikkens produkter fra testkatalogen, med varepriser og lenker til produktvisningene på SjekkPris.</p></header>
<dl class="store-facts"><div><dt>produkter i utvalget</dt><dd>{count}</dd></div><div><dt>produktgrupper</dt><dd>{len(groups)}</dd></div><div><dt>merke</dt><dd>1</dd></div></dl>
<p class="muted">Designforslag · Øyeblikksbilde fra testkatalogen 18. oktober 2026. Prisene på denne siden oppdateres ikke løpende.</p>
<nav class="store-nav" aria-label="På butikksiden"><a href="#store-products">Produkter</a><a href="#store-insights">Utvalg og innsikt</a><a href="#store-about">Om butikken</a></nav>
<section class="store-section" id="store-products" aria-labelledby="store-products-title"><h2 id="store-products-title">Produkter fra Baby Brezza</h2><p class="muted">Varepriser uten frakt. Åpne produktet for å se det nyeste tilgjengelige tilbudet.</p>
<div id="store-controls" hidden><div class="store-toolbar"><label for="store-query">Søk i butikkens produkter<input id="store-query" type="search" placeholder="Søk etter produktnavn"></label><label for="store-sort">Sorter etter<select id="store-sort"><option value="name">Produktnavn A–Å</option><option value="price">Laveste varepris</option></select></label></div><div class="store-filters" role="group" aria-label="Produktgruppe">{chips}</div></div>
<p id="store-status" class="store-results-status" role="status">{count} produkter i øyeblikksbildet</p><ul class="store-products">{''.join(cards)}</ul><button type="button" class="store-more" id="store-more" hidden>Vis alle {count} produkter</button><div class="store-empty" id="store-empty" hidden><h3>Ingen produkter passer søket</h3><p>Prøv et annet produktnavn eller vis hele utvalget.</p><button type="button" id="store-reset">Nullstill søk og filtre</button></div></section>
<div class="store-lower"><section class="store-panel" id="store-insights" aria-labelledby="store-insights-title"><h2 id="store-insights-title">Utvalg og innsikt</h2><p>Dette finner du fra butikken i vårt testutvalg.</p><ul class="store-bars">{bars}</ul><p class="muted">Teller unike produktsider med tilbud fra «babybrezza» i øyeblikksbildet. Farge- og pakningsvarianter med egne produktsider telles separat. Dette er ikke butikkens fulle sortiment.</p><div class="store-popularity"><h3>Mest klikket fra SjekkPris</h3><p>Vi har ikke nok dokumenterte klikkdata til å vise en toppliste ennå.</p><p class="muted">Her kan du senere se hvilke produkter flest har klikket videre til butikken fra, de siste 30 dagene. Dette vil ikke være en liste over butikkens bestselgere.</p></div></section>
<section class="store-panel store-about" id="store-about" aria-labelledby="store-about-title"><h2 id="store-about-title">Om Baby Brezza</h2><p>Baby Brezza-nettbutikken tilbyr blant annet maskiner for tilberedning av morsmelkerstatning, flaskevarmere, sterilisatorer og utstyr for flaskerengjøring.</p><dl><div><dt>Nettbutikk</dt><dd><a href="https://babybrezza.no/">babybrezza.no ↗</a></dd></div><div><dt>Oppgitt virksomhet på butikkens nettsted</dt><dd>IBP Scandinavia AB · Göteborg, Sverige</dd></div><div><dt>Butikkinformasjon kontrollert</dt><dd>18. oktober 2026</dd></div></dl><h3>Frakt og levering</h3><p>Fraktbeløp og leveringstid er ikke oppgitt i tilbudene vi har hentet til dette forslaget. Kontroller vilkårene for bestillingen hos butikken.</p><a class="store-link" href="https://babybrezza.no/pages/shipping-and-returns">Frakt og retur hos butikken ↗</a><h3>Kjøp og kundeservice</h3><p>Du handler hos Baby Brezza. Spørsmål om bestilling og retur håndteres av butikken.</p><a class="store-link" href="https://babybrezza.no/pages/contact">Kontakt butikken ↗</a></section></div>
<details class="store-sources"><summary>Om opplysningene på denne siden</summary><p>Dette er et designforslag med en datert kopi av offentlig tilgjengelige opplysninger, redigert av SjekkPris. Ingen popularitet, anmeldelser eller prisvurderinger er konstruert.</p><ul><li>Produktnavn, bilder og varepriser: SjekkPris sin offentlige testkatalog, hentet 18.10.2026. Hvert produktkort lenker til sin kildeside.</li><li>Butikkbeskrivelse, virksomhet og logo: <a href="https://babybrezza.no/">Baby Brezzas eget nettsted</a>, kontrollert 18.10.2026.</li><li>Produktgruppene er redaksjonelt samlet for dette forslaget. Vi hevder ikke at en butikk er billigst når sammenligningsgrunnlaget mangler.</li></ul><p class="muted">Siden er en del av designbetaen og er ikke åpnet for søkeindeksering.</p></details></article>'''+SCRIPT
    target=out/'butikker/babybrezza';target.mkdir(parents=True,exist_ok=True)
    (target/'index.html').write_text(page('Baby Brezza – produkter og butikkoversikt',body,base='/',noindex=True),encoding='utf-8')
